import { PageHeader, Section } from '@/components/layout/PageHeader'
import { CodeBlock } from '@/components/common/Code'
import { Ref } from '@/components/common/Ref'

export default function Overview() {
  return <>
<PageHeader eyebrow="Week 05 · 기본 학습 2/10" title={"02. pgvector 전체 구조"} />
<Section id="section-1" title={"1. pgvector란?"}>
<p><code>{"pgvector"}</code>{"는 PostgreSQL에서 vector를 저장하고 검색할 수 있게 해주는 오픈소스 확장입니다."}</p>
<CodeBlock language="sql">{"CREATE EXTENSION vector;\n\nCREATE TABLE documents (\n    id BIGSERIAL PRIMARY KEY,\n    content TEXT,\n    embedding VECTOR(1536)\n);"}</CodeBlock>
<p>{"검색 예:"}</p>
<CodeBlock language="sql">{"SELECT *\nFROM documents\nORDER BY embedding <=> :query_vector\nLIMIT 10;"}</CodeBlock>
</Section>
<Section id="section-2" title={"2. pgvector의 검색 방식"}>
<CodeBlock language="text">{"pgvector\n│\n├── Exact Search\n│   └── 모든 후보와 정확한 거리 계산\n│\n└── Approximate Search\n    ├── HNSW\n    └── IVFFlat"}</CodeBlock>
<p>{"기본적으로 인덱스를 만들지 않으면 exact nearest neighbor search가 가능합니다."}</p>
<p>{"ANN 인덱스를 추가하면 일부 Recall을 희생하는 대신 검색 속도를 높일 수 있습니다."}</p>
</Section>
<Section id="section-3" title={"3. HNSW와 IVFFlat"}>
<p>{"pgvector 공식 문서의 핵심 비교:"}</p>
<h3>{"HNSW"}</h3>
<ul><li>{"multilayer graph"}</li><li>{"IVFFlat보다 일반적으로 speed-recall trade-off가 좋음"}</li><li>{"build 시간이 더 오래 걸림"}</li><li>{"메모리 사용량이 큼"}</li><li>{"별도의 training 단계 없이 빈 테이블에도 생성 가능"}</li></ul>
<h3>{"IVFFlat"}</h3>
<ul><li>{"k-means 기반으로 list/cluster 생성"}</li><li>{"데이터 분포를 먼저 학습해야 함"}</li><li>{"HNSW보다 build가 가벼운 편"}</li><li><code>{"lists"}</code>{", "}<code>{"probes"}</code>{"가 중요한 파라미터"}</li></ul>
</Section>
<h2 id="section-4" className="mt-12 text-[21px] font-semibold">{"4. 인덱스 예"}</h2>
<Section id="section-5" title={"HNSW"}>
<CodeBlock language="sql">{"CREATE INDEX document_embedding_hnsw\nON documents\nUSING hnsw (embedding vector_cosine_ops);"}</CodeBlock>
<p>{"조정:"}</p>
<CodeBlock language="sql">{"SET hnsw.ef_search = 100;"}</CodeBlock>
<p>{"일반적으로 "}<code>{"ef_search"}</code>{"를 늘리면:"}</p>
<CodeBlock language="text">{"탐색 후보 ↑\nRecall ↑\nLatency ↑"}</CodeBlock>
</Section>
<Section id="section-6" title={"IVFFlat"}>
<CodeBlock language="sql">{"CREATE INDEX document_embedding_ivf\nON documents\nUSING ivfflat (embedding vector_cosine_ops)\nWITH (lists = 1000);"}</CodeBlock>
<p>{"검색 시:"}</p>
<CodeBlock language="sql">{"SET ivfflat.probes = 10;"}</CodeBlock>
<p><code>{"probes"}</code>{" 증가:"}</p>
<CodeBlock language="text">{"검색할 cluster 수 ↑\nRecall ↑\nLatency ↑"}</CodeBlock>
</Section>
<Section id="section-7" title={"5. Filter가 있는 경우"}>
<CodeBlock language="sql">{"SELECT *\nFROM documents\nWHERE category_id = 10\nORDER BY embedding <=> :query\nLIMIT 10;"}</CodeBlock>
<p>{"ANN 인덱스를 사용할 때 일반적인 문제는:"}</p>
<CodeBlock language="text">{"vector candidate 탐색\n        ↓\nWHERE filter\n        ↓\n결과 부족 가능"}</CodeBlock>
<p>{"예:"}</p>
<CodeBlock language="text">{"HNSW가 40개 candidate 탐색\ncategory 조건 통과율 = 10%\n\n평균 통과 결과 ≈ 4개"}</CodeBlock>
<p>{"하지만 사용자는 "}<code>{"LIMIT 10"}</code>{"을 요청했습니다."}</p>
</Section>
<Section id="section-8" title={"6. Iterative Index Scan"}>
<p>{"pgvector 0.8.0부터 필터 결과가 부족하면 인덱스를 더 탐색할 수 있습니다."}</p>
<p>{"HNSW:"}</p>
<CodeBlock language="sql">{"SET hnsw.iterative_scan = strict_order;"}</CodeBlock>
<p>{"또는:"}</p>
<CodeBlock language="sql">{"SET hnsw.iterative_scan = relaxed_order;"}</CodeBlock>
<p>{"IVFFlat:"}</p>
<CodeBlock language="sql">{"SET ivfflat.iterative_scan = relaxed_order;"}</CodeBlock>
<p>{"제한값도 설정할 수 있습니다."}</p>
<CodeBlock language="sql">{"SET hnsw.max_scan_tuples = 20000;\nSET ivfflat.max_probes = 100;"}</CodeBlock>
<p>{"이 기능 때문에 최신 pgvector를 설명할 때:"}</p>
<blockquote><p>{"필터링 이후 결과가 부족해도 무조건 처음 candidate 개수에서 끝난다."}</p></blockquote>
<p>{"라고 설명하면 안 됩니다."}</p>
</Section>
<Section id="section-9" title={"7. pgvector와 pgvectorscale의 관계"}>
<p><code>{"pgvectorscale"}</code>{"은 pgvector를 대체하는 기술이라기보다 "}<strong>{"pgvector 위에 대규모 벡터 검색 기능을 추가하는 확장"}</strong>{"입니다."}</p>
<CodeBlock language="text">{"PostgreSQL\n   │\n   ├── pgvector\n   │    ├── vector type\n   │    ├── exact search\n   │    ├── HNSW\n   │    └── IVFFlat\n   │\n   └── pgvectorscale\n        ├── StreamingDiskANN\n        ├── SBQ\n        └── Label-based Filtered Search"}</CodeBlock>
<p>{"공식 표현으로 pgvectorscale은 pgvector를 "}<strong>{"complement"}</strong>{"합니다."}</p>
</Section>
<Section id="section-10" title={"8. pgvector가 RAM만 신뢰하는가?"}>
<p>{"아닙니다."}</p>
<p>{"HNSW/IVFFlat 인덱스는 PostgreSQL 인덱스이므로 디스크/SSD에 저장됩니다."}</p>
<p>{"실제 접근은 다음과 같습니다."}</p>
<CodeBlock language="text">{"Query\n  ↓\nPostgreSQL\n  ↓\nshared_buffers\n  ↓ cache miss\nOS page cache\n  ↓ cache miss\nSSD / Disk"}</CodeBlock>
<p>{"따라서 HNSW의 핵심 문제는:"}</p>
<blockquote><p>{"RAM에만 저장된다는 것"}</p></blockquote>
<p>{"이 아니라"}</p>
<blockquote><p>{"graph random access가 많아서 working set이 cache에 없으면 random I/O가 증가할 수 있다는 것"}</p></blockquote>
<p>{"입니다."}</p>
<p>{"이 차이를 정확히 기억해야 합니다."}</p>
</Section>
<Section id="section-11" title={"참고"}>
<ul><li><a className="break-all" href={"https://github.com/pgvector/pgvector"}>{"https://github.com/pgvector/pgvector"}</a></li><li><a className="break-all" href={"https://github.com/timescale/pgvectorscale"}>{"https://github.com/timescale/pgvectorscale"}</a></li></ul>
</Section>
<p className="prose-doc mt-10">다음 → <Ref to="/pgvector/ivfflat">{"03. IVFFlat"}</Ref></p>
  </>
}
